// Builds one theme stylesheet from the token source: every token as a CSS custom property,
// for each color mode and density.
//
// Property names carry the prefix `--rc-`. Without it, names such as --color-red-500 and
// --radius-md would collide with the theme variables of Tailwind CSS in a consuming app.
import { rgba } from "../color.js";
import { compose, DENSITIES, loadSource, MODES } from "../load.js";
import { aliasTarget, resolvedType, resolveToken } from "../resolve.js";

const BASE = { mode: MODES[0], density: DENSITIES[0] };
const HEADER =
  "/* GENERATED by raincoat-tokens from the token source. Do not edit: change tokens/ and rebuild. */";

// A typography token becomes one property per field.
const TYPOGRAPHY_FIELDS = [
  ["fontFamily", "font-family", "fontFamily"],
  ["fontSize", "font-size", "dimension"],
  ["fontWeight", "font-weight", "fontWeight"],
  ["letterSpacing", "letter-spacing", "dimension"],
  ["lineHeight", "line-height", "number"],
];

// CSS keywords that must not be quoted in a font-family list.
const GENERIC_FAMILIES = new Set([
  "serif",
  "sans-serif",
  "monospace",
  "cursive",
  "fantasy",
  "system-ui",
  "ui-serif",
  "ui-sans-serif",
  "ui-monospace",
  "ui-rounded",
  "emoji",
  "math",
  "fangsong",
]);

const FONT_WEIGHTS = {
  thin: 100,
  hairline: 100,
  "extra-light": 200,
  "ultra-light": 200,
  light: 300,
  normal: 400,
  regular: 400,
  book: 400,
  medium: 500,
  "semi-bold": 600,
  "demi-bold": 600,
  bold: 700,
  "extra-bold": 800,
  "ultra-bold": 800,
  black: 900,
  heavy: 900,
  "extra-black": 950,
  "ultra-black": 950,
};

const hexByte = (channel) =>
  Math.round(channel * 255)
    .toString(16)
    .padStart(2, "0");

/** A resolved token value, written as CSS. Colors are hex so that every tool can read them. */
export function cssValue(type, value) {
  switch (type) {
    case "color": {
      const { r, g, b, a } = rgba(value);
      return `#${hexByte(r)}${hexByte(g)}${hexByte(b)}${a < 1 ? hexByte(a) : ""}`;
    }
    case "dimension":
    case "duration":
      return `${value.value}${value.unit}`;
    case "fontFamily":
      return []
        .concat(value)
        .map((name) => (GENERIC_FAMILIES.has(name) ? name : `"${name.replaceAll('"', '\\"')}"`))
        .join(", ");
    case "fontWeight":
      return String(FONT_WEIGHTS[value] ?? value);
    case "cubicBezier":
      return `cubic-bezier(${value.join(", ")})`;
    case "shadow":
      return []
        .concat(value)
        .map((layer) =>
          [
            layer.inset ? "inset" : null,
            cssValue("dimension", layer.offsetX),
            cssValue("dimension", layer.offsetY),
            cssValue("dimension", layer.blur),
            cssValue("dimension", layer.spread),
            cssValue("color", layer.color),
          ]
            .filter(Boolean)
            .join(" "),
        )
        .join(", ");
    default:
      return String(value);
  }
}

/**
 * The custom properties for one composed token set.
 * @returns {{name: string, value: string, resolved: string}[]} `value` keeps a `var()`
 *   reference where the token refers to another token; `resolved` is the final value.
 */
export function declarations(tokens) {
  const result = [];
  const reference = (id, suffix = "") => `var(--rc-${tokens.get(id).name}${suffix})`;

  for (const token of tokens.values()) {
    const type = resolvedType(token.id, tokens);
    const resolved = resolveToken(token.id, tokens);
    const target = aliasTarget(token.value);

    if (type === "typography") {
      for (const [field, suffix, fieldType] of TYPOGRAPHY_FIELDS) {
        const fieldTarget = target ? null : aliasTarget(token.value[field]);
        result.push({
          name: `--rc-${token.name}-${suffix}`,
          value: target
            ? reference(target, `-${suffix}`)
            : fieldTarget
              ? reference(fieldTarget)
              : cssValue(fieldType, token.value[field]),
          resolved: cssValue(fieldType, resolved[field]),
        });
      }
    } else {
      const final = cssValue(type, resolved);
      result.push({
        name: `--rc-${token.name}`,
        value: target ? reference(target) : final,
        resolved: final,
      });
    }
  }
  return result;
}

const block = (selector, entries, indent = "") =>
  [
    `${indent}${selector} {`,
    ...entries.map(({ name, value }) => `${indent}  ${name}: ${value};`),
    `${indent}}`,
  ].join("\n");

/**
 * Builds the theme stylesheet.
 *
 * The first block holds every token for the light mode at comfortable density. Each further
 * block holds only what differs, and it includes every token whose *resolved* value differs,
 * not just the ones redefined in the source. That is what makes a mode work on a nested
 * element: a component token such as --button-primary-bg-default is declared again inside
 * [data-theme="dark"], so it resolves against the dark values there.
 */
export function buildThemeCss(root) {
  const files = loadSource(root);
  const load = (permutation) => declarations(compose(files, permutation).tokens);

  const base = load(BASE);
  const baseResolved = new Map(base.map((entry) => [entry.name, entry.resolved]));
  const differences = (permutation) =>
    load(permutation).filter((entry) => entry.resolved !== baseResolved.get(entry.name));

  const modes = Object.fromEntries(
    MODES.slice(1).map((mode) => [mode, differences({ mode, density: BASE.density })]),
  );
  const compact = differences({ mode: BASE.mode, density: "compact" });

  const unset = ":root:not([data-theme])";
  const media = (query, entries) => `@media ${query} {\n${block(unset, entries, "  ")}\n}`;

  return `${[
    HEADER,
    block(`:root,\n[data-theme="${BASE.mode}"]`, base),
    ...MODES.slice(1).map((mode) => block(`[data-theme="${mode}"]`, modes[mode])),
    block('[data-density="compact"]', compact),
    "/* When no mode is set explicitly, follow the system's preferences. */",
    media("(prefers-color-scheme: dark)", modes.dark),
    media("(prefers-contrast: more)", modes["light-hc"]),
    media("(prefers-color-scheme: dark) and (prefers-contrast: more)", modes["dark-hc"]),
  ].join("\n\n")}\n`;
}
